(function(root){
'use strict';

const CREATED='2026-09-08';
const EXTERNAL_REFERENCES=Object.freeze({
  'SOP-EXT-001':'Externer Druck- bzw. ERP-Prozess für Lieferschein und physische Dokumentausgabe',
  'SOP-EXT-002':'Externes Zollsystem für die eigentliche Ausfuhranmeldung / ABD-Erstellung',
  'SOP-EXT-003':'Externes Versand- oder Speditionsportal für Transportauftrag, Label oder Buchung',
  'SOP-EXT-004':'Externes E-Mail-Programm für den eigentlichen Versand einer vorbereiteten Nachricht',
  'SOP-EXT-005':'Externes ERP-/Stammdatensystem für Änderungen außerhalb des ExportHUB',
  'SOP-EXT-006':'Kundenspezifisches oder sonstiges externes Portal'
});
const AREA_OWNER=Object.freeze({
  'System-Grundlagen':'Systemadministration',
  'Benutzer, Firmen und Rechte':'Systemadministration / Firmen-Admin',
  'Kunden und Standorte':'Firmen-Admin / Versandkoordination',
  'Sendungen':'Versandkoordination',
  'Versandkosten und Transport':'Versandkoordination',
  'Dokumente und Ausgabe':'Versandkoordination',
  'ABD und Mail':'Exportkoordination',
  'QR, POD und Kunden-Avis':'Versandkoordination',
  'Palettenkonto':'Versand / Lager',
  'Aufgaben, Planer und Abholkalender':'Teamleitung / Versandkoordination',
  'SOP und Academy':'Funktions-Admin / Qualitätsverantwortlicher',
  'Archiv, Diagnose, Release und App':'Systemadministration'
});
function list(v){return Array.isArray(v)?v:(v?[v]:[]);}
function shortLabel(text){let out=String(text||'').replace(/^Im ExportHUB\s+/i,'').replace(/[.;:].*$/,'').trim();if(out.length>42)out=out.slice(0,39).trim()+'…';return out||'Systemschritt';}
function externalText(code){return `Der folgende Arbeitsschritt findet außerhalb von ExportHUB statt. Weitere Durchführung siehe ${code}.`;}
function systemDiagramSrc(nodes,input){
  const clean=value=>String(value==null?'':value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]||ch));
  const list=Array.isArray(nodes)?nodes.slice(0,5):[];
  const width=Math.max(720,list.length*180+40),height=220;
  const items=list.map((label,index)=>{
    const x=25+index*180;
    const arrow=index<list.length-1?`<line x1="${x+140}" y1="118" x2="${x+172}" y2="118" stroke="#64748b" stroke-width="3"/><path d="M ${x+164} 109 L ${x+174} 118 L ${x+164} 127" fill="none" stroke="#64748b" stroke-width="3"/>`:'';
    return `<g><rect x="${x}" y="76" width="140" height="84" rx="14" fill="#f8fafc" stroke="#94a3b8"/><circle cx="${x+22}" cy="98" r="14" fill="#1d4ed8"/><text x="${x+22}" y="103" text-anchor="middle" font-family="Arial,sans-serif" font-size="13" font-weight="700" fill="white">${index+1}</text><text x="${x+70}" y="129" text-anchor="middle" font-family="Arial,sans-serif" font-size="12" font-weight="700" fill="#0f172a">${clean(label)}</text></g>${arrow}`;
  }).join('');
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="100%" height="100%" fill="white"/><rect x="18" y="18" width="${width-36}" height="42" rx="10" fill="#e2e8f0"/><text x="38" y="45" font-family="Arial,sans-serif" font-size="18" font-weight="700" fill="#0f172a">ExportHUB · ${clean(input.number)} · ${clean(input.title)}</text>${items}<text x="25" y="198" font-family="Arial,sans-serif" font-size="11" fill="#475569">Systemgrafik aus den freigegebenen ExportHUB-Arbeitsschritten – keine Darstellung externer Software.</text></svg>`;
  return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function buildVisuals(input,sections){const nodes=list(input.flow).length?list(input.flow):sections.steps.slice(0,5).map(step=>shortLabel(step.text||step));return [{type:'process',stepId:'process-flow',caption:`Prozessübersicht – ${input.number}: ${input.title}`,required:true},{type:'screenshot',stepId:'step-1',caption:`ExportHUB-Systembild – ${input.title}`,required:true,nodes:nodes.slice(0,5),src:systemDiagramSrc(nodes,input)}];}
function define(input){
  const owner=input.processOwner||AREA_OWNER[input.area]||'Prozessverantwortlicher';const refs=list(input.references);const steps=list(input.steps).map((text,index)=>({id:`step-${index+1}`,number:index+1,text}));
  const sections={purpose:input.purpose||`Diese SOP beschreibt ausschließlich die Bedienung des ExportHUB für den Systemprozess „${input.title}“. Sie stellt sicher, dass der Vorgang einheitlich, nachvollziehbar und mit den vorgesehenen Systemprüfungen durchgeführt wird.`,scope:input.scope||`ExportHUB · ${input.area}. Die SOP gilt für Benutzer, die für diesen Bereich mindestens Leserechte und für Änderungen die erforderlichen Schreibrechte besitzen.`,definitions:list(input.definitions),responsibilities:list(input.responsibilities).length?list(input.responsibilities):['Der angemeldete Benutzer führt nur die in dieser SOP beschriebenen ExportHUB-Schritte aus und prüft die angezeigten Ergebnisse.',`${owner} stellt sicher, dass Rollen, Berechtigungen und fachliche Vorgaben für diesen Systemprozess korrekt hinterlegt sind.`],prerequisites:list(input.prerequisites).length?list(input.prerequisites):['Der Benutzer ist im richtigen Firmenkontext angemeldet.','Die für den Vorgang erforderlichen ExportHUB-Rechte sind vorhanden.','Benötigte Stammdaten oder Vorgangsdaten sind bereits im System vorhanden oder werden in dieser SOP erfasst.'],resources:['ExportHUB in der aktuell freigegebenen gemeinsamen Version','Die in der jeweiligen Ansicht angezeigten Systemdaten und Statusinformationen'].concat(list(input.resources)),steps,checks:list(input.checks).length?list(input.checks):['Vor dem Speichern prüfen, ob der richtige Datensatz und die richtige Firma geöffnet sind.','Nach der Aktion die sichtbare Bestätigung, den Status oder die geänderten Daten kontrollieren.','Bei einer Fehlermeldung nicht wiederholt blind auslösen, sondern den angezeigten Fehler prüfen.'],deviations:list(input.deviations).length?list(input.deviations):['Kann ein Systemschritt nicht wie beschrieben abgeschlossen werden, den Vorgang nicht durch eine unkontrollierte Umgehung fortsetzen. Fehlerdiagnose öffnen und gemäß SOP-EH-112 weiterarbeiten.'],records:list(input.records).length?list(input.records):['ExportHUB-Datensatz','Systemstatus / Zeitstempel','Änderungs- oder Ereignishistorie, soweit im jeweiligen Bereich vorhanden'],metrics:list(input.metrics),relatedDocuments:list(input.relatedDocuments),references:refs,changeHistory:[{version:'1.0',date:CREATED,status:'Entwurf',change:'RC1008 – vollständige Neufassung als reine ExportHUB-System-SOP'}]};
  return Object.freeze({id:input.number,number:input.number,title:input.title,area:input.area,keywords:list(input.keywords).concat(input.title.split(/\s+/).filter(Boolean)),processFlow:list(input.flow).length?list(input.flow):steps.slice(0,5).map(step=>shortLabel(step.text)),version:'1.0',status:'Entwurf',validFrom:'',createdBy:'ExportHUB – RC1008 SOP-Ersterstellung',reviewedBy:'',approvedBy:'',processOwner:owner,affectedAreas:[input.area],nextReview:'',changeReason:'RC1008 – Umstellung auf reine ExportHUB-Systemprozesse',sections,visuals:buildVisuals(input,sections),references:refs,history:sections.changeHistory});
}
function item(number,title,steps,options={}){return define(Object.assign({number,title,steps},options));}

const documents=[
item('SOP-EH-001','Anmeldung und Start im ExportHUB',['ExportHUB über den freigegebenen Einstieg öffnen und prüfen, ob die Anmeldeseite vollständig geladen wurde.','Benutzername und Passwort beziehungsweise die freigegebene Microsoft-Anmeldung verwenden.','Anmeldung auslösen und auf die Systemprüfung warten; die Anmeldung nicht mehrfach parallel starten.','Nach erfolgreicher Anmeldung prüfen, ob Startseite, Firmenkontext und persönliche Rolle korrekt geladen sind.','Bei abgewiesener Anmeldung die eingeblendete Meldung lesen und erst nach Klärung erneut anmelden.'],{area:'System-Grundlagen',flow:['Anmeldeseite öffnen','Zugangsdaten eingeben','Systemprüfung abwarten','Startseite prüfen'],keywords:['Login','Microsoft','Passwort']}),
item('SOP-EH-002','Startseite, Navigation und Zurück-Navigation',['Nach der Anmeldung die Startseite öffnen und die verfügbaren Kacheln sowie das Seitenmenü prüfen.','Den benötigten Bereich über die zugehörige Kachel oder den Menüeintrag öffnen.','Vor Eingaben kontrollieren, ob Überschrift und geöffneter Bereich zur beabsichtigten Funktion passen.','Für einen Bereichswechsel die Navigation verwenden; den Browser-Reload nur verwenden, wenn der Systemablauf dies erfordert.','Mit der vorgesehenen Zurück-Navigation zur vorherigen ExportHUB-Ansicht zurückkehren und prüfen, ob Filter und Position erhalten bleiben.'],{area:'System-Grundlagen',flow:['Startseite öffnen','Bereich auswählen','Ansicht prüfen','Zurück navigieren']}),
item('SOP-EH-003','Globale Suche und Bereichsfilter verwenden',['Das Suchfeld in der Topbar oder im jeweiligen Funktionsbereich öffnen.','Eindeutigen Suchbegriff wie Referenz, Kunde, Sendungsnummer, Aufgabe oder SOP-Nummer eingeben.','Zusätzliche Filter nur setzen, wenn die Treffermenge weiter eingegrenzt werden muss.','Den passenden Treffer anhand von Nummer, Titel, Kunde, Datum oder Status identifizieren und öffnen.','Nicht mehr benötigte Filter zurücksetzen, damit nachfolgende Suchen nicht unbemerkt eingeschränkt bleiben.'],{area:'System-Grundlagen',flow:['Suchbegriff eingeben','Filter setzen','Treffer prüfen','Datensatz öffnen']}),
item('SOP-EH-004','Dashboard, Warncenter und Benachrichtigungscenter',['Dashboard nach der Anmeldung aufrufen und die angezeigten Arbeitsinformationen prüfen.','Warncenter öffnen und handlungsrelevante Prozess- oder Fehlerwarnungen zuerst bearbeiten.','Benachrichtigungscenter öffnen und neue Ereignisse sowie Informationsmeldungen prüfen.','Eine Meldung anklicken, wenn sie direkt zu einem ExportHUB-Datensatz oder einer Funktion führt.','Nach Bearbeitung kontrollieren, ob Warnung beziehungsweise Benachrichtigung entsprechend dem Systemstatus aktualisiert wurde.'],{area:'System-Grundlagen',flow:['Dashboard prüfen','Warncenter öffnen','Benachrichtigungen prüfen','Meldung öffnen']}),
item('SOP-EH-005','Benutzerprofil, Sitzung und Abmeldung',['Persönlichen Profil- beziehungsweise Sitzungsbereich in ExportHUB öffnen.','Angezeigten Benutzer, Firma und Rolle prüfen.','Bei Bedarf die vorhandenen Sitzungsinformationen kontrollieren.','Für einen sicheren Benutzerwechsel die aktuelle Sitzung über Abmelden beenden.','Nach der Abmeldung prüfen, dass geschützte ExportHUB-Bereiche nicht mehr ohne neue Anmeldung geöffnet werden können.'],{area:'System-Grundlagen',flow:['Profil öffnen','Benutzer prüfen','Sitzung prüfen','Abmelden']}),
item('SOP-EH-006','Firmenauswahl und Systemumgebung prüfen',['Nach Anmeldung die angezeigte Firma beziehungsweise bei Systemadministratoren die Firmenauswahl prüfen.','Die Firma auswählen, in deren Datenbestand gearbeitet werden soll.','Vor Änderungen kontrollieren, dass Firmenname und Kontext zur beabsichtigten Bearbeitung passen.','Die angezeigte Systemumgebung Produktion, TESTSERVICE oder Demo prüfen, wenn eine solche Kennzeichnung sichtbar ist.','Bei falschem Kontext keine Daten ändern, sondern zuerst Firma oder Umgebung korrigieren.'],{area:'System-Grundlagen',flow:['Firmenkontext prüfen','Firma auswählen','Umgebung prüfen','Bearbeitung starten']}),
item('SOP-EH-007','App-Benachrichtigung direkt im ExportHUB öffnen',['Auf dem Mobilgerät eine ExportHUB-Benachrichtigung antippen.','Prüfen, ob die App direkt den zugehörigen ExportHUB-Bereich oder die Fehlerdiagnose öffnet.','Die angezeigte Meldung mit Vorgang, Firma und Status abgleichen.','Die erforderliche Aktion im geöffneten ExportHUB-Bereich durchführen.','Falls die Benachrichtigung nicht zum Ziel führt, Fehlerdiagnose öffnen und den Deep-Link-Fehler dokumentieren.'],{area:'System-Grundlagen',flow:['Benachrichtigung antippen','Zielansicht öffnen','Vorgang prüfen','Aktion durchführen'],references:['SOP-EH-113']}),
item('SOP-EH-010','Benutzerübersicht öffnen und Benutzer finden',['Bereich Benutzer öffnen.','Benutzerliste anhand von Name, E-Mail, Firma, Rolle und Status prüfen.','Bei Bedarf Suche oder Filter verwenden, um den gewünschten Benutzer eindeutig zu finden.','Den Benutzer öffnen und vor einer Änderung Identität sowie Firmenzuordnung kontrollieren.','Nur im richtigen Benutzerkonto weiterarbeiten.'],{area:'Benutzer, Firmen und Rechte',flow:['Benutzerbereich öffnen','Benutzer suchen','Zuordnung prüfen','Benutzer öffnen']}),
item('SOP-EH-011','Benutzer anlegen und Benutzerdaten bearbeiten',['Benutzerbereich öffnen und die Funktion zum Anlegen eines neuen Benutzers wählen.','Erforderliche Stammdaten wie Name, E-Mail beziehungsweise Benutzerkennung erfassen.','Firma und vorgesehene Rolle auswählen.','Eingaben auf Tippfehler und eindeutige Zuordnung prüfen und speichern.','Bei einem bestehenden Benutzer zuerst dessen Datensatz öffnen, nur die erforderlichen Felder ändern und erneut speichern.','Nach dem Speichern prüfen, ob der Benutzer in der Übersicht mit den erwarteten Daten erscheint.'],{area:'Benutzer, Firmen und Rechte',flow:['Benutzer anlegen','Stammdaten erfassen','Firma und Rolle wählen','Speichern']}),
item('SOP-EH-012','Rollen, Rechte und Firmenzuordnung verwalten',['Benutzer öffnen und den Bereich Rollen beziehungsweise Berechtigungen aufrufen.','Aktuelle Rolle und Firmenzuordnung prüfen.','Nur die tatsächlich benötigte Rolle auswählen; Rechte nicht pauschal erweitern.','Bei Firmen-Admin beziehungsweise HSE/Sicherheitsverantwortlich prüfen, ob der Zugriff auf die eigene Firma beschränkt bleibt.','Änderung speichern und die sichtbare Rollen- und Rechteanzeige erneut kontrollieren.','Bei kritischen Rollenänderungen den Zugriff mit einem geeigneten Benutzerkonto gegenprüfen.'],{area:'Benutzer, Firmen und Rechte',flow:['Benutzer öffnen','Rolle prüfen','Rechte zuweisen','Speichern','Zugriff kontrollieren']}),
item('SOP-EH-013','Benutzer deaktivieren, löschen und aktive Sitzung beenden',['Betroffenen Benutzer eindeutig über Name, E-Mail und Firma identifizieren.','Prüfen, ob der Benutzer deaktiviert, vollständig gelöscht oder nur eine aktive Sitzung beendet werden soll.','Die vorgesehene Aktion über die Benutzerverwaltung auslösen.','Eine Sicherheitsabfrage vollständig lesen und nur bei korrektem Benutzer bestätigen.','Nach Abschluss prüfen, ob Status, Benutzerliste und gegebenenfalls aktive Sitzungen aktualisiert wurden.'],{area:'Benutzer, Firmen und Rechte',flow:['Benutzer identifizieren','Aktion auswählen','Bestätigen','Ergebnis prüfen']}),
item('SOP-EH-014','Sichtbarkeit und Zugriff nach Rollen prüfen',['Mit der zu prüfenden Rolle im korrekten Firmenkontext anmelden.','Navigation und Startseite kontrollieren: nicht berechtigte Bereiche dürfen nicht als nutzbare Funktionen angeboten werden.','Einen zulässigen Bereich öffnen und prüfen, ob Lesen beziehungsweise Bearbeiten entsprechend der Rolle möglich ist.','Direktzugriffe auf fremde Firmen, gesperrte Funktionen oder Dokumente testen, wenn eine Rechteänderung verifiziert werden muss.','Bei unerwarteter Sichtbarkeit oder Zugriff den Vorgang abbrechen und die Rechteverwaltung korrigieren.'],{area:'Benutzer, Firmen und Rechte',flow:['Mit Rolle anmelden','Navigation prüfen','Zugriff testen','Abweichung korrigieren'],references:['SOP-EH-012']}),
item('SOP-EH-020','Kundenübersicht und Kundenstammdaten verwalten',['Bereich Kunden öffnen und die Kundenübersicht laden.','Kunden über Kundennummer oder Namen suchen.','Vor Änderungen prüfen, dass die Kundennummer eindeutig zum geöffneten Kunden gehört.','Erforderliche Kundendaten im ExportHUB ergänzen oder korrigieren.','Änderungen speichern und anschließend erneut in der Übersicht prüfen.',externalText('SOP-EXT-005')],{area:'Kunden und Standorte',flow:['Kunde suchen','Stammdaten prüfen','Daten ändern','Speichern'],references:['SOP-EXT-005']}),
item('SOP-EH-021','Kundenstandorte anlegen, zuordnen und auswählen',['Kunden öffnen und den Bereich Standorte aufrufen.','Vorhandene Standorte prüfen und sicherstellen, dass sie nur dem geöffneten Kunden zugeordnet sind.','Neuen Standort mit vollständiger Adresse anlegen oder einen bestehenden Standort bearbeiten.','Standort speichern und in der Standortliste des Kunden kontrollieren.','Bei einer Sendung nur einen Standort auswählen, der dem gewählten Kunden zugeordnet ist.'],{area:'Kunden und Standorte',flow:['Kunde öffnen','Standorte prüfen','Standort anlegen','Zuordnung speichern']}),
item('SOP-EH-022','Kundenkontakte, Maildaten und Kundenordner verwenden',['Kunden öffnen und Kontakt- beziehungsweise Mailbereich auswählen.','Ansprechpartner, E-Mail-Daten und vorhandene Hinweise prüfen.','Kundenordner öffnen und die für den Kunden gespeicherten Unterlagen kontrollieren.','Nur die für den geöffneten Kunden bestimmten Dokumente und Kontaktdaten verwenden.','Änderungen oder neue Dokumente speichern und Zuordnung erneut prüfen.'],{area:'Kunden und Standorte',flow:['Kunde öffnen','Kontakte prüfen','Kundenordner öffnen','Zuordnung prüfen']}),
item('SOP-EH-023','Kundendokumente öffnen, herunterladen und Direktzugriff prüfen',['Kunden- oder Sendungsdatensatz öffnen, zu dem das Dokument gehört.','Dokumentenliste öffnen und das gewünschte Dokument anhand von Typ und Dateiname auswählen.','Dokument öffnen oder herunterladen.','Prüfen, dass der Zugriff nur innerhalb der eigenen Firma und vorhandenen Berechtigung möglich ist.','Bei einer fremden oder falschen Datei den Zugriff abbrechen und Fehlerdiagnose beziehungsweise Rechteprüfung starten.'],{area:'Kunden und Standorte',flow:['Datensatz öffnen','Dokument auswählen','Öffnen oder laden','Berechtigung prüfen'],references:['SOP-EH-014','SOP-EH-112']}),
item('SOP-EH-030','Sendungsübersicht suchen, filtern und öffnen',['Bereich Sendungen öffnen.','Suchbegriff wie Referenz, Kunde oder Sendungsnummer eingeben.','Status- oder Datumsfilter nur bei Bedarf ergänzen.','Trefferliste anhand von Kunde, Empfänger, Status und Abholinformationen prüfen.','Die gewünschte Sendung öffnen und vor der Bearbeitung Referenz sowie Empfänger kontrollieren.'],{area:'Sendungen',flow:['Sendungen öffnen','Suchen und filtern','Treffer prüfen','Sendung öffnen']}),
item('SOP-EH-031','Neue Sendung im ExportHUB anlegen',['Funktion Neue Sendung öffnen.','Kunde und Empfänger beziehungsweise Standort auswählen.','Erforderliche Sendungsdaten erfassen.','Mindestens eine korrekte Verpackungs-/Colli-Zeile ergänzen.','Dokumenten-, ABD-, Stauplan- und Mailbereiche auf notwendige Eingaben prüfen.','Pflichtfelder kontrollieren und Sendung als Entwurf oder vollständig speichern.','Nach dem Speichern prüfen, ob die Sendung mit eindeutiger Referenz in der Übersicht vorhanden ist.'],{area:'Sendungen',flow:['Neue Sendung öffnen','Kunde auswählen','Sendungsdaten erfassen','Colli erfassen','Speichern']}),
item('SOP-EH-032','Kunde, Empfänger und Sendungsdaten in einer Sendung erfassen',['In der geöffneten Sendung den Bereich Kunde/Empfänger aufrufen.','Kunde auswählen und ausschließlich einen diesem Kunden zugeordneten Standort verwenden.','Empfängeradresse auf Vollständigkeit und richtiges Land prüfen.','Im Bereich Sendungsdaten Transportart, Abholdatum, Warenbeschreibung, Incoterm und vorhandene Referenzdaten erfassen.','Besonderheiten oder Kundenhinweise in den vorgesehenen Feldern hinterlegen.','Vor dem Weiterarbeiten die sichtbaren Pflichtfeldhinweise prüfen.'],{area:'Sendungen',flow:['Kunde auswählen','Standort wählen','Empfänger prüfen','Sendungsdaten erfassen']}),
item('SOP-EH-033','Verpackung, Colli, Gewicht, Maße und LDM erfassen',['Bereich Colli/LDM der Sendung öffnen.','Passende Verpackungsart auswählen.','Tatsächliche physische Anzahl der Verpackungseinheiten eingeben.','Gewicht sowie Länge, Breite und Höhe erfassen beziehungsweise aus hinterlegten Verpackungsdaten übernehmen.','Automatisch berechnete oder ergänzte LDM auf Plausibilität prüfen.','Weitere Colli-Zeilen hinzufügen, ohne bestehende Eingaben zu überschreiben.','Gesamtanzahl, Gesamtgewicht und LDM vor dem Speichern kontrollieren.'],{area:'Sendungen',flow:['Verpackung wählen','Anzahl eingeben','Gewicht und Maße erfassen','LDM prüfen','Summen kontrollieren']}),
item('SOP-EH-034','Stauplan erstellen, prüfen und speichern',['In der Sendung den Bereich Stauplan öffnen.','Vor Erstellung prüfen, ob Colli, Maße und Anzahl vollständig erfasst sind.','Automatische Stauplanerstellung auslösen.','Darstellung der Ladeeinheiten, Ausrichtung und verfügbaren Ladefläche prüfen.','Erforderliche manuelle Anpassungen nur über die vorgesehenen Stauplan-Funktionen durchführen.','Stauplan speichern und anschließend erneut aus der Sendung öffnen, um die Speicherung zu kontrollieren.'],{area:'Sendungen',flow:['Colli prüfen','Stauplan erzeugen','Anordnung prüfen','Anpassen','Speichern'],references:['SOP-EH-033']}),
item('SOP-EH-035','Sendung als Entwurf speichern und später weiterbearbeiten',['Unvollständige Sendung mit bereits bekannten Daten erfassen.','Funktion Als Entwurf speichern verwenden, wenn noch keine vollständige Sendungsfreigabe möglich ist.','Nach dem Speichern prüfen, ob Status und eingegebene Daten erhalten bleiben.','Sendung später über die Übersicht erneut öffnen.','Fehlende Daten ergänzen, Pflichtfelder erneut prüfen und anschließend normal speichern.'],{area:'Sendungen',flow:['Daten erfassen','Entwurf speichern','Entwurf wieder öffnen','Vervollständigen']}),
item('SOP-EH-036','Bestehende Sendung bearbeiten und Änderungen speichern',['Sendung über die Sendungsübersicht öffnen.','Prüfen, ob der aktuelle Status eine Bearbeitung noch zulässt.','Nur die erforderlichen Felder oder Bereiche ändern.','Vor dem Speichern Colli, Dokumente, ABD-Status und andere abhängige Angaben auf Folgewirkungen prüfen.','Änderungen speichern und sichtbare Bestätigung abwarten.','Sendung erneut prüfen, um sicherzustellen, dass die Änderungen dauerhaft übernommen wurden.'],{area:'Sendungen',flow:['Sendung öffnen','Bearbeitbarkeit prüfen','Daten ändern','Speichern','Ergebnis prüfen']}),
item('SOP-EH-037','Sendungsstatus, Sperre, Storno und Nachbearbeitung verwalten',['Sendung öffnen und aktuellen Status in der Statuskette prüfen.','Nur einen fachlich zulässigen Folgestatus auswählen beziehungsweise durch die zugehörige Systemaktion erzeugen.','Ab Status Abgeholt beziehungsweise bei vorhandenem POD prüfen, dass versandrelevante Kerndaten nur noch lesbar sind.','Für ein Storno die vorgesehene Stornofunktion verwenden und Sicherheitsabfrage bestätigen.','Für erforderliche Korrekturen die vorgesehene Nachbearbeitungsfunktion verwenden, statt gesperrte Daten zu umgehen.','Statusänderung und Zeitstempel in Übersicht beziehungsweise Historie kontrollieren.'],{area:'Sendungen',flow:['Status prüfen','Folgestatus ausführen','Sperre beachten','Storno/Nachbearbeitung','Historie prüfen']}),
item('SOP-EH-038','Sendung abschließen und archivieren',['Sendung öffnen und prüfen, ob Abholung sowie alle erforderlichen Nachweise abgeschlossen sind.','POD-Status und vorhandene Pflichtdokumente prüfen.','Funktion zum Abschließen der Sendung ausführen.','Status Abgeschlossen kontrollieren.','Wenn die Sendung archiviert werden soll, Archivierungsfunktion aufrufen und bestätigen.','Im Archiv prüfen, ob der Datensatz weiterhin vollständig lesbar und historisch nachvollziehbar ist.'],{area:'Sendungen',flow:['Voraussetzungen prüfen','Abschließen','Status kontrollieren','Archivieren','Archiv prüfen'],references:['SOP-EH-075','SOP-EH-110']}),
item('SOP-EH-040','Versandkosten mit Gate41, UPS und Zuschlägen ermitteln',['Versandkostenbereich der Sendung öffnen.','Prüfen, ob Zielland, Verpackung, Gewicht und erforderliche Routendaten korrekt aus der Sendung übernommen wurden.','Gewünschte Kostenquelle Gate41 oder UPS auswählen.','Preisabfrage auslösen und auf ein vollständiges Ergebnis warten.','Angezeigte Frachtkosten sowie vorhandene Maut- oder sonstige Zuschläge prüfen.','Ein Ergebnis von 0,00 EUR bei erwarteten Kosten nicht ungeprüft übernehmen, sondern Fehlerdiagnose beziehungsweise Routendaten prüfen.','Gewählten Preis beziehungsweise Kostenstand in der Sendung speichern.'],{area:'Versandkosten und Transport',flow:['Routendaten prüfen','Kostenquelle wählen','Preis abfragen','Zuschläge prüfen','Kosten speichern']}),
item('SOP-EH-041','Zielland, Route und Versanddienstleister prüfen',['Sendung öffnen und Empfängerland beziehungsweise Standort prüfen.','Versandkosten- oder Transportbereich öffnen und kontrollieren, welches Zielland das System erkannt hat.','Bei falschem Land zuerst Empfänger- und Standortdaten korrigieren; keine internationale Preisberechnung mit falscher Route übernehmen.','Passenden Versanddienstleister beziehungsweise Transportweg auswählen.','Auswahl speichern und erneut prüfen, bevor ein externer Buchungsschritt begonnen wird.'],{area:'Versandkosten und Transport',flow:['Empfängerland prüfen','Route prüfen','Dienstleister wählen','Speichern'],references:['SOP-EH-021','SOP-EH-040']}),
item('SOP-EH-042','Transportdaten an ein externes Versandportal übergeben',['Im ExportHUB Sendung, Empfänger, Colli, Gewicht und gewählten Versanddienstleister vollständig prüfen.','Im Transportbereich die für die externe Buchung benötigten Daten beziehungsweise Unterlagen bereitstellen.','ExportHUB-Datensatz speichern, bevor in ein Fremdsystem gewechselt wird.',externalText('SOP-EXT-003'),'Nach Abschluss des externen Schritts in ExportHUB zurückkehren und erforderliche Referenz, Kosten oder Statusinformationen im vorgesehenen Feld hinterlegen.'],{area:'Versandkosten und Transport',flow:['Transportdaten prüfen','Übergabe vorbereiten','Extern buchen','Rückmeldung hinterlegen'],references:['SOP-EXT-003']}),
item('SOP-EH-050','Dokumente hochladen und einer Sendung zuordnen',['Sendung öffnen und den Dokumentenbereich aufrufen.','Passenden Dokumenttyp auswählen.','Datei über Upload-Funktion auswählen beziehungsweise ablegen.','Upload vollständig abschließen lassen und keine Seite während eines laufenden Uploads verlassen.','Dateiname, Dokumenttyp und Sendungszuordnung prüfen.','Dokument öffnen, um Lesbarkeit und korrekte Datei zu kontrollieren.'],{area:'Dokumente und Ausgabe',flow:['Dokumentenbereich öffnen','Dokumenttyp wählen','Datei hochladen','Zuordnung prüfen','Dokument öffnen']}),
item('SOP-EH-051','Pflichtdokumente und Dokumentenstatus prüfen',['Dokumenten- beziehungsweise Prüfbereich der Sendung öffnen.','Angezeigte Pflichtdokumente anhand des Sendungsfalls prüfen.','Status vorhanden, ausstehend oder nicht erforderlich je Dokument kontrollieren.','Fehlende Dokumente über die vorgesehene Upload- oder Erzeugungsfunktion ergänzen.','Versandsperrende Hinweise nicht ignorieren.','Nach Ergänzung die Dokumentenprüfung erneut ausführen beziehungsweise Anzeige aktualisieren.'],{area:'Dokumente und Ausgabe',flow:['Pflichtliste öffnen','Status prüfen','Fehlendes Dokument ergänzen','Erneut prüfen']}),
item('SOP-EH-052','Ladeliste, L1/QR und L2 im ExportHUB erzeugen',['Sendung vollständig öffnen und Colli- sowie Empfängerdaten prüfen.','Ausgabe-/Druckbereich öffnen.','Ladeliste beziehungsweise vorgesehenes L1/QR- und L2-Dokument auswählen.','Erzeugung starten und warten, bis die Dokumentansicht vollständig aufgebaut wurde.','Referenz, Kunde, Empfänger, Colli und QR-Darstellung an der vorgesehenen Stelle prüfen.','Fehlerhafte oder leere Ausgabe nicht verwenden, sondern Daten korrigieren und neu erzeugen.'],{area:'Dokumente und Ausgabe',flow:['Sendungsdaten prüfen','Ausgabe öffnen','Dokument erzeugen','Inhalt prüfen']}),
item('SOP-EH-053','CMR im ExportHUB erzeugen und prüfen',['Sendung öffnen und prüfen, ob für den Versandfall ein CMR benötigt wird.','CMR-Funktion im Dokumenten-/Ausgabebereich öffnen.','Übernommene Absender-, Empfänger-, Colli-, Warenbeschreibungs- und Gewichtsdaten prüfen.','CMR erzeugen.','Erzeugtes CMR vollständig anzeigen und prüfen, ob keine Felder leer oder einer anderen Sendung zugeordnet sind.','Dokument speichern beziehungsweise zur Gesamtausgabe übernehmen.'],{area:'Dokumente und Ausgabe',flow:['CMR-Bedarf prüfen','Daten kontrollieren','CMR erzeugen','Ausgabe prüfen']}),
item('SOP-EH-054','Gesamtdruck, PDF und Download ausführen',['Sendung öffnen und vor der Gesamtausgabe die Dokumentenprüfung durchführen.','Gesamtdruck beziehungsweise Gesamtausgabe auswählen.','Erzeugung starten und Ladefortschritt abwarten.','Dokumentenreihenfolge, Seitenanzahl und Inhalte prüfen; leere Zusatzseiten dürfen nicht verwendet werden.','PDF öffnen oder herunterladen und Dateiinhalte kontrollieren.','Bei einer fehlerhaften Ausgabe Ursache im betroffenen Dokument beheben und Gesamtausgabe neu erzeugen.'],{area:'Dokumente und Ausgabe',flow:['Dokumente prüfen','Gesamtausgabe starten','PDF erzeugen','Seiten prüfen','Download']}),
item('SOP-EH-055','Lieferschein im ExportHUB prüfen und extern drucken',['Sendung beziehungsweise Dokumentenbereich öffnen und den zugehörigen Lieferschein auswählen.','Im ExportHUB prüfen, ob der richtige Lieferschein der richtigen Sendung zugeordnet ist.','Dokument öffnen beziehungsweise für die Ausgabe bereitstellen.',externalText('SOP-EXT-001'),'Nach dem externen Druck in ExportHUB zurückkehren und den Vorgang ohne Änderung der Dokumentzuordnung fortsetzen.'],{area:'Dokumente und Ausgabe',flow:['Lieferschein auswählen','Zuordnung prüfen','Ausgabe bereitstellen','Extern drucken'],references:['SOP-EXT-001']}),
item('SOP-EH-056','Dokument öffnen, herunterladen und bei fehlender Datei reagieren',['Dokumentenliste des Vorgangs öffnen.','Dokument anhand von Typ und Dateiname auswählen.','Öffnen oder Download auslösen.','Bei einer verständlichen Fehlermeldung wie fehlender Datei keinen fremden Blob- oder Direktlink manuell verwenden.','Wenn die Datei tatsächlich fehlt, den vorgesehenen erneuten Upload durchführen und anschließend erneut öffnen.','Bei wiederholtem Fehler Fehlerdiagnose öffnen.'],{area:'Dokumente und Ausgabe',flow:['Dokument auswählen','Öffnen/Download','Fehler prüfen','Neu hochladen'],references:['SOP-EH-050','SOP-EH-112']}),
item('SOP-EH-060','ABD-Bedarf und Status im ExportHUB prüfen',['Sendung öffnen und Zielland sowie relevanten Warenwert prüfen.','ABD-/Dokumentenbereich öffnen.','Vom System angezeigten ABD-Bedarf anhand Nicht-EU, Warenwert und vorhandener Speditionsanforderung kontrollieren.','Bei ABD-Pflicht prüfen, ob bereits ein gültiges ABD hinterlegt ist.','Fehlt das ABD, den vorgesehenen Wartestatus beziehungsweise die Anforderung verwenden.','Bei nicht plausibler ABD-Entscheidung die Sendungsdaten korrigieren, bevor fortgefahren wird.'],{area:'ABD und Mail',flow:['Zielland/Wert prüfen','ABD-Bedarf prüfen','Vorhandenes ABD prüfen','Wartestatus setzen']}),
item('SOP-EH-061','ABD anfordern, hochladen und mehrere ABD verwalten',['ABD-Bereich der Sendung öffnen.','Erforderliche Referenz beziehungsweise Sendungszuordnung prüfen.','ABD-Anforderung im ExportHUB auslösen oder ein bereits erhaltenes ABD über die vorgesehene Upload-Funktion hinterlegen.','Bei mehreren ABD-Dateien jede Datei einzeln der gleichen Sendung korrekt zuordnen.','Referenz, Dateiname und Dokumentstatus je ABD kontrollieren.','Nach dem letzten erforderlichen ABD die Dokumenten- und Versandfreigabe erneut prüfen.'],{area:'ABD und Mail',flow:['ABD-Bereich öffnen','Anfordern/hochladen','Mehrere ABD zuordnen','Status prüfen']}),
item('SOP-EH-062','Status „Wartet auf ABD“ und Versandfreigabe verwalten',['Sendung mit festgestellter ABD-Pflicht öffnen.','Status Wartet auf ABD beziehungsweise die vom System vorgesehene Sperre setzen.','Prüfen, dass versandsperrende Aktionen bis zum erforderlichen ABD nicht normal abgeschlossen werden können.','Nach Eingang ABD hochladen beziehungsweise zuordnen.','Dokumentenprüfung erneut ausführen.','Erst nach erfolgreicher Prüfung die vorgesehene weitere Versandbearbeitung fortsetzen.'],{area:'ABD und Mail',flow:['Wartestatus setzen','Versandsperre prüfen','ABD hinterlegen','Erneut prüfen','Freigeben'],references:['SOP-EH-061']}),
item('SOP-EH-063','Mailbereich, Vorlagen, Anhänge und Pflicht-CC verwenden',['Sendung öffnen und den einmal vorhandenen Mailbereich aufrufen.','Passende Mailart beziehungsweise Vorlage wählen und Sprache Deutsch oder Englisch prüfen.','Empfänger, Betreff und automatisch übernommene Sendungsdaten kontrollieren.','Erforderliche Dokumente als Anhänge auswählen.','Pflicht-CC-Empfänger gemäß Systemvorgabe prüfen und nicht unbeabsichtigt entfernen.','Nachricht als vorbereitet beziehungsweise bestätigt markieren, wenn die jeweilige Systemfunktion dies vorsieht.','Vor Übergabe an das E-Mail-Programm den finalen Inhalt noch einmal prüfen.'],{area:'ABD und Mail',flow:['Mailbereich öffnen','Vorlage wählen','Empfänger/CC prüfen','Anhänge wählen','Inhalt prüfen']}),
item('SOP-EH-064','ABD- oder Versandmail extern versenden und Rückmeldung im ExportHUB pflegen',['Mail im ExportHUB gemäß SOP-EH-063 vollständig vorbereiten.','Prüfen, dass Empfänger, CC, Sprache und Anhänge korrekt sind.',externalText('SOP-EXT-004'),'Nach Rückkehr in ExportHUB den vorgesehenen Mailstatus beziehungsweise Bestätigungsstatus pflegen.','Bei einer extern erhaltenen Referenz oder Rückmeldung diese nur im dafür vorgesehenen ExportHUB-Feld hinterlegen.'],{area:'ABD und Mail',flow:['Mail vorbereiten','Daten prüfen','Extern versenden','Status pflegen'],references:['SOP-EH-063','SOP-EXT-004']}),
item('SOP-EH-065','Externe Zollanmeldung aus ExportHUB vorbereiten',['Sendung und ABD-Bedarf im ExportHUB prüfen.','Für die Zollanmeldung erforderliche Sendungs- und Dokumentdaten vollständig bereitstellen.','ExportHUB-Sendungsstand speichern und Wartestatus setzen.',externalText('SOP-EXT-002'),'Nach Erhalt des ABD in ExportHUB zurückkehren und gemäß SOP-EH-061 hochladen und zuordnen.'],{area:'ABD und Mail',flow:['ABD-Bedarf prüfen','Daten bereitstellen','Wartestatus setzen','Extern anmelden','ABD hinterlegen'],references:['SOP-EH-060','SOP-EH-061','SOP-EXT-002']}),
item('SOP-EH-070','QR-Abholung für eine Sendung erzeugen',['Sendung öffnen und prüfen, ob sie für die Abholung vorbereitet ist.','QR-Abholfunktion aufrufen.','QR-/Token-Erzeugung auslösen und auf die erfolgreiche Systembestätigung warten.','Prüfen, dass der QR-Zugang der richtigen Sendung zugeordnet ist.','Ladeliste beziehungsweise vorgesehene Ausgabe erneut prüfen, wenn der QR-Code dort verwendet wird.'],{area:'QR, POD und Kunden-Avis',flow:['Sendung prüfen','QR-Funktion öffnen','QR erzeugen','Zuordnung prüfen']}),
item('SOP-EH-071','Öffentliche Abholseite über QR öffnen und Sendung prüfen',['QR-Code mit dem vorgesehenen Gerät öffnen beziehungsweise scannen.','Öffentliche Abholseite vollständig laden lassen.','Angezeigte Referenz, Empfänger und Abholinformationen mit der tatsächlichen Sendung abgleichen.','Nur bei korrekter Sendung mit PIN- beziehungsweise Colli-Prüfung fortfahren.','Bei ungültigem oder abgelaufenem Link nicht manuell eine andere Sendung verwenden, sondern gemäß SOP-EH-074 diagnostizieren.'],{area:'QR, POD und Kunden-Avis',flow:['QR scannen','Abholseite laden','Sendung prüfen','Weiter zur Bestätigung'],references:['SOP-EH-074']}),
item('SOP-EH-072','Verlade-PIN und Colli bei der Abholung bestätigen',['Auf der geöffneten Abholseite die PIN-Eingabe aufrufen.','Gültigen Verlade-PIN eingeben und Bestätigung auslösen.','Soll-Colli-Anzahl mit der tatsächlichen Abholung vergleichen.','Tatsächliche beziehungsweise bestätigte Colli-Anzahl im vorgesehenen Feld erfassen.','Bei Abweichung nicht ungeprüft bestätigen, sondern die Sendungsdaten beziehungsweise Verladung klären.','Erst bei korrektem PIN und geklärter Colli-Anzahl die Abholung final bestätigen.'],{area:'QR, POD und Kunden-Avis',flow:['PIN eingeben','PIN prüfen','Colli vergleichen','Colli bestätigen','Abholung bestätigen']}),
item('SOP-EH-073','Abholung finalisieren und Status mit Zeitstempel prüfen',['Nach erfolgreicher PIN-/Colli-Prüfung die Abholung endgültig bestätigen.','Auf die erfolgreiche Systemmeldung warten.','Sendung im internen ExportHUB erneut öffnen.','Status Abgeholt sowie tatsächliches Datum und Uhrzeit kontrollieren.','Prüfen, dass die vorgesehene Bearbeitungssperre für Kerndaten aktiv ist.','Bei fehlender Statusänderung keine zweite Abholung erzeugen, sondern Diagnose durchführen.'],{area:'QR, POD und Kunden-Avis',flow:['Abholung bestätigen','Systemmeldung prüfen','Sendung öffnen','Status/Zeit prüfen','Sperre prüfen'],references:['SOP-EH-037','SOP-EH-112']}),
item('SOP-EH-074','Ungültigen QR-, Token- oder Abhollink diagnostizieren',['Fehlermeldung auf der öffentlichen Abholseite vollständig lesen.','Im internen ExportHUB die zugehörige Sendung anhand der Referenz öffnen.','Prüfen, ob bereits eine Abholung erfolgt ist oder der Zugang deaktiviert beziehungsweise abgelaufen ist.','QR-Abholstatus und erforderliche Systemdaten kontrollieren.','Nur wenn fachlich zulässig einen neuen QR-Zugang über die vorgesehene Funktion erzeugen.','Bei weiterhin ungültigem Link Fehlerdiagnose öffnen und Diagnoseinformationen sichern.'],{area:'QR, POD und Kunden-Avis',flow:['Fehler lesen','Sendung öffnen','Zugangsstatus prüfen','QR ggf. neu erzeugen','Diagnose öffnen'],references:['SOP-EH-070','SOP-EH-112']}),
item('SOP-EH-075','POD hochladen, prüfen und Status setzen',['Sendung öffnen und prüfen, ob sie bereits als abgeholt geführt wird.','POD-Bereich öffnen und Datei auswählen.','POD hochladen und vollständigen Upload abwarten.','Dokument öffnen und auf richtige Sendung, Lesbarkeit sowie relevanten Abliefernachweis prüfen.','POD-Zuordnung speichern.','Status POD vorhanden beziehungsweise den vom System vorgesehenen Folgestatus kontrollieren.','Mehrere POD-Dateien nur hinzufügen, wenn sie tatsächlich zur gleichen Sendung gehören.'],{area:'QR, POD und Kunden-Avis',flow:['Abholstatus prüfen','POD hochladen','Dokument prüfen','Zuordnung speichern','Status prüfen']}),
item('SOP-EH-076','Kunden-Avis aktivieren und sicheren Link erzeugen',['Sendung öffnen und Kunden-Avis-Bereich aufrufen.','Prüfen, ob die Sendung eine gültige Referenz und die für das Avis benötigten Daten besitzt.','Kunden-Avis aktivieren.','Auf die serverseitige Erzeugung des sicheren Links warten.','Angezeigten Avis-Status und die Link-Gültigkeit prüfen.','Link nur über die vorgesehene Kopier-/Mailfunktion weiterverwenden; keinen eigenen Token manuell konstruieren.'],{area:'QR, POD und Kunden-Avis',flow:['Sendung öffnen','Avis aktivieren','Sicheren Link erzeugen','Status prüfen']}),
item('SOP-EH-077','Kunden-Avis deaktivieren, Gültigkeit und Freigaben prüfen',['Aktives Kunden-Avis der Sendung öffnen.','Status, Aktivierungszeit und gegebenenfalls Ablaufzeit prüfen.','Prüfen, welche Sendungsdaten und Dokumente für die öffentliche Avisansicht freigegeben sind.','Bei Bedarf Avis über die vorgesehene Funktion deaktivieren.','Nach der Deaktivierung prüfen, dass der Status in ExportHUB aktualisiert wurde.','Bei automatischem Ablauf kontrollieren, dass der Zugang entsprechend der Systemregel nicht länger aktiv ist.'],{area:'QR, POD und Kunden-Avis',flow:['Avis öffnen','Gültigkeit prüfen','Freigaben prüfen','Deaktivieren','Status prüfen']}),
item('SOP-EH-078','Öffentliche Kunden-Avis-Seite kontrollieren',['Den im ExportHUB erzeugten Kunden-Avis-Link über die vorgesehene Prüfmöglichkeit öffnen.','Kontrollieren, dass keine interne Anmeldung und keine internen Navigationsbereiche angezeigt werden.','Prüfen, dass ausschließlich die für diese Sendung freigegebenen Daten und Dokumente sichtbar sind.','Versuchen, keine Daten einer anderen Firma oder Sendung über die öffentliche Ansicht aufzurufen.','Bei falschen oder zu umfangreichen Daten den Avis-Zugang sofort deaktivieren und Fehlerdiagnose starten.'],{area:'QR, POD und Kunden-Avis',flow:['Avis-Link öffnen','Öffentliche Ansicht prüfen','Freigaben kontrollieren','Fehler sperren'],references:['SOP-EH-077','SOP-EH-112']}),
item('SOP-EH-080','Palettenkonto öffnen und Bestand prüfen',['Bereich Palettenkonto öffnen.','Richtigen Kunden beziehungsweise Geschäftspartner auswählen, wenn der Kontostand partnerbezogen geführt wird.','Aktuellen Europalettenbestand sowie letzte Buchungen prüfen.','Eingänge und Ausgänge auf Plausibilität kontrollieren.','Vor einer neuen Buchung sicherstellen, dass dieselbe Bewegung nicht bereits erfasst wurde.'],{area:'Palettenkonto',flow:['Palettenkonto öffnen','Partner prüfen','Bestand prüfen','Letzte Buchungen prüfen']}),
item('SOP-EH-081','Paletteneingang oder -ausgang buchen – Referenz optional',['Palettenkonto öffnen und Eingang oder Ausgang auswählen.','Anzahl der Europaletten als positive ganze Menge eingeben.','Referenz nur eintragen, wenn eine Referenz vorhanden beziehungsweise fachlich gewünscht ist; das Feld darf für normale Buchungen leer bleiben.','Buchungsart und Menge vor dem Speichern erneut prüfen.','Buchung auslösen und auf Bestätigung warten.','Neuen Bestand und Buchungszeile prüfen.'],{area:'Palettenkonto',flow:['Buchungsart wählen','Menge eingeben','Referenz optional','Buchen','Bestand prüfen']}),
item('SOP-EH-082','Palettenbuchung per QR durchführen',['Im Palettenkonto die QR-Funktion für die vorgesehene Buchungsart öffnen.','QR-Code der zugehörigen Sendung beziehungsweise Buchungsquelle scannen.','Vom System übernommene Zuordnung und Buchungsrichtung prüfen.','Menge kontrollieren beziehungsweise ergänzen.','Buchung bestätigen und anschließend Bestand sowie Historie prüfen.'],{area:'Palettenkonto',flow:['QR-Funktion öffnen','QR scannen','Zuordnung prüfen','Menge prüfen','Buchen']}),
item('SOP-EH-083','Palettenhistorie, Tausch und Korrekturbuchung prüfen',['Palettenkonto und Buchungshistorie öffnen.','Betroffene Buchung anhand von Datum, Art, Menge und vorhandener Referenz identifizieren.','Bei einem Tausch die dafür vorgesehene Buchungsart beziehungsweise Kennzeichnung verwenden.','Eine erforderliche Ausgleichs- oder Korrekturbuchung nur mit entsprechender Berechtigung anlegen.','Keine vorhandene Buchung unkontrolliert überschreiben.','Nach Korrektur neuen Bestand und nachvollziehbare Historie prüfen.'],{area:'Palettenkonto',flow:['Historie öffnen','Buchung identifizieren','Tausch/Korrektur erfassen','Bestand prüfen']}),
item('SOP-EH-090','Aufgabenübersicht, Aufgabe anlegen und zuweisen',['Bereich Aufgaben öffnen und vorhandene Aufgaben über Suche, Bereich oder Status prüfen.','Funktion Neue Aufgabe öffnen.','Titel, Beschreibung und erforderlichen Sendungs- beziehungsweise Prozessbezug erfassen.','Zuständigen Benutzer oder Bereich auswählen.','Fälligkeit und Priorität festlegen.','Aufgabe speichern und in der Übersicht auf korrekte Zuordnung prüfen.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Aufgaben öffnen','Neue Aufgabe anlegen','Zuweisen','Fälligkeit/Priorität setzen','Speichern']}),
item('SOP-EH-091','Aufgabenpriorität, Fälligkeit, Erinnerung und Status pflegen',['Aufgabe öffnen.','Aktuelle Priorität und Fälligkeit prüfen und bei Bedarf über die vorgesehenen Felder ändern.','Erinnerungszeitpunkte auswählen beziehungsweise anpassen.','Status offen, in Arbeit oder erledigt entsprechend dem tatsächlichen Bearbeitungsstand setzen.','Änderung speichern.','Aufgabenübersicht prüfen, ob Termin, Priorität und Status korrekt aktualisiert wurden.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Aufgabe öffnen','Termin/Priorität ändern','Erinnerung setzen','Status ändern','Speichern']}),
item('SOP-EH-092','Wiederkehrende Aufgaben verwalten',['Aufgabe öffnen und Wiederholungsfunktion aufrufen.','Gewünschtes Wiederholungsintervall auswählen.','Start- und gegebenenfalls Endbedingung prüfen.','Wiederholung speichern.','Nach Erledigung einer Instanz prüfen, dass für den nächsten Zeitraum eine neue Aufgabe erzeugt wird und nicht der erledigte Datensatz wieder geöffnet wird.','Bei fehlerhafter Wiederholung keine alten Aufgaben manuell duplizieren, sondern Regel korrigieren.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Aufgabe öffnen','Wiederholung festlegen','Speichern','Folgeaufgabe prüfen']}),
item('SOP-EH-093','Urlaub und Vertretung in der Aufgabenplanung berücksichtigen',['Planungs- beziehungsweise Aufgabenbereich öffnen.','Abwesenheit oder Urlaub der betroffenen Person prüfen beziehungsweise erfassen, soweit diese Funktion im ExportHUB vorgesehen ist.','Vertretung auswählen beziehungsweise betroffene Aufgaben auf die vorgesehene Vertretung umplanen.','Fälligkeiten und Verantwortlichkeiten prüfen.','Änderungen speichern und in der Aufgabenübersicht kontrollieren.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Abwesenheit prüfen','Vertretung wählen','Aufgaben umplanen','Speichern']}),
item('SOP-EH-094','Drag-and-Drop im Aufgabenplaner und Lager verwenden',['Planer oder Lageransicht öffnen und die zu verschiebende Aufgabe beziehungsweise Kachel eindeutig identifizieren.','Element per Drag-and-Drop auf die vorgesehene Zielfläche ziehen.','Auf die visuelle Bestätigung der neuen Zuordnung warten.','Prüfen, ob Status, Verantwortlichkeit, Bereich oder Termin entsprechend der Zielspalte aktualisiert wurde.','Bei unbeabsichtigtem Verschieben die vorgesehene Korrektur durchführen und nicht mehrfach schnell hin- und herziehen.','Nach mehreren Planungsänderungen stichprobenartig prüfen, ob keine anderen Elemente ihren Status übernommen haben.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Element wählen','Ziel bestimmen','Verschieben','Zuordnung prüfen']}),
item('SOP-EH-095','Abholkalender und fixe Abholungen verwenden',['Abholkalender öffnen.','Gewünschten Tag beziehungsweise Zeitraum auswählen.','Angemeldete Sendungen und fixe Abholungen getrennt prüfen.','Sendungskarte öffnen, wenn Detaildaten oder Colli-Status benötigt werden.','Eine neue fixe Abholung nur über die vorgesehene Kalenderfunktion erfassen beziehungsweise ändern.','Nach Änderung Kalenderansicht und Termin prüfen.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Kalender öffnen','Tag auswählen','Abholungen prüfen','Termin bearbeiten']}),
item('SOP-EH-096','Lagerkacheln und Zielflächen im ExportHUB prüfen',['Lager-/Planungsansicht öffnen.','Kacheln anhand von Bereich, Status, Termin und farblicher Kennzeichnung prüfen.','Zielflächen wie DAF oder definierte Lagerorte eindeutig auswählen.','Kachel über die vorgesehene Systemfunktion zuordnen oder verschieben.','Neue Position beziehungsweise Status kontrollieren.','Bei falscher oder fehlender Zielfläche keine freie Textposition erfinden, sondern die Stammdaten-/Konfigurationsfunktion verwenden.'],{area:'Aufgaben, Planer und Abholkalender',flow:['Lageransicht öffnen','Kachel prüfen','Zielfläche wählen','Zuordnen','Ergebnis prüfen']}),
item('SOP-EH-100','SOP-Handbuch öffnen, suchen, filtern und lesen',['Bereich SOP öffnen.','SOP über Nummer, Titel oder Stichwort suchen.','Bei Bedarf Bereichs- oder Statusfilter setzen.','Gewünschtes gelenktes Dokument öffnen.','SOP-Nummer, Version und Status im Dokumentenkopf prüfen.','Schritt-für-Schritt-Ablauf einschließlich Prozessgrafik und Systembild lesen.'],{area:'SOP und Academy',flow:['SOP-Bereich öffnen','Suchen/filtern','SOP öffnen','Version prüfen','Ablauf lesen']}),
item('SOP-EH-101','Neue SOP-Fassung anlegen und Inhalt bearbeiten',['Freigegebene oder vorhandene SOP öffnen.','Funktion Neue Fassung verwenden und eindeutige neue Versionsnummer vergeben.','Änderungsgrund eintragen.','Nur die neue Entwurfsfassung bearbeiten; die freigegebene Fassung nicht überschreiben.','Zweck, Voraussetzungen, Arbeitsschritte, Prüfpunkte, Nachweise und Querverweise vollständig pflegen.','Entwurf speichern und Vollständigkeitsstatus prüfen.'],{area:'SOP und Academy',flow:['SOP öffnen','Neue Fassung anlegen','Inhalt bearbeiten','Speichern','Vollständigkeit prüfen']}),
item('SOP-EH-102','Prozessgrafiken und Systembilder in SOPs verwenden',['SOP-Entwurf öffnen und den zu bebildernden Systemablauf prüfen.','Nur eine ExportHUB-Systemgrafik verwenden, die aus den in dieser SOP beschriebenen Schritten erzeugt wurde; keine erfundene Fremdsoftware-Oberfläche darstellen.','Systembild dem passenden Arbeitsschritt zuordnen.','Bildbeschriftung prüfen, damit eindeutig erkennbar ist, welchen ExportHUB-Schritt die Grafik erklärt.','Vollständigkeitsprüfung ausführen und sicherstellen, dass kein Pflicht-Bildplatzhalter offen bleibt.'],{area:'SOP und Academy',flow:['SOP-Entwurf öffnen','Systemablauf ableiten','Bild erzeugen','Schritt zuordnen','Vollständigkeit prüfen']}),
item('SOP-EH-103','SOP zur Prüfung einreichen, freigeben, Historie prüfen und archivieren',['Fertigen SOP-Entwurf öffnen und Vollständigkeitsanzeige prüfen.','Funktion Zur Prüfung verwenden.','Prüfstatus und verantwortliche Person kontrollieren.','Nach erfolgreicher Prüfung die vorgesehene Freigabefunktion verwenden.','Status Freigegeben, Versionsnummer und Gültig-ab-Datum prüfen.','Versionshistorie öffnen und sicherstellen, dass die vorherige freigegebene Fassung historisch erhalten bleibt.','Eine nicht mehr gültige SOP nur über die Archivierungsfunktion archivieren.'],{area:'SOP und Academy',flow:['Vollständigkeit prüfen','Zur Prüfung','Freigeben','Historie prüfen','Archivieren']}),
item('SOP-EH-104','SOP drucken und gelenkte Version erkennen',['SOP öffnen und vor dem Drucken Nummer, Version und Freigabestatus prüfen.','Druckfunktion im SOP-Dokument verwenden.','Druckvorschau auf vollständigen Dokumentenkopf, Arbeitsschritte, Tabellen und Bilder prüfen.','Druck beziehungsweise PDF-Ausgabe auslösen.','Papier- oder PDF-Kopie nur als aktuelle Arbeitskopie verwenden, wenn Version und Freigabestatus noch gültig sind.'],{area:'SOP und Academy',flow:['SOP öffnen','Version prüfen','Druckvorschau','Ausgeben']}),
item('SOP-EH-105','Academy öffnen und eine Prüfung starten',['Bereich Academy beziehungsweise Prüfungen öffnen.','Verfügbaren Beruf-/Themenbereich auswählen.','Freigegebene Prüfung öffnen und angezeigte Anzahl sowie Hinweise prüfen.','Prüfung starten.','Fragen in der angezeigten Reihenfolge bearbeiten und Antwortauswahl speichern.','Vor Abgabe prüfen, ob alle erforderlichen Fragen beantwortet wurden.','Prüfung abgeben und Ergebnisanzeige öffnen.'],{area:'SOP und Academy',flow:['Academy öffnen','Prüfung auswählen','Starten','Fragen beantworten','Abgeben']}),
item('SOP-EH-106','Prüfungen auswerten, nachbesprechen und verwalten',['Als berechtigter Funktions-Admin den Prüfungsbereich öffnen.','Prüfung beziehungsweise Teilnehmerergebnis auswählen.','Punktestand, beantwortete Fragen und Auswertung prüfen.','Nachbesprechungsansicht öffnen und fehlerhafte Antworten mit den vorgesehenen Erläuterungen durchgehen.','Bei der Prüfungsverwaltung sicherstellen, dass veröffentlichte und nicht veröffentlichte Änderungen eindeutig gekennzeichnet sind.','Änderungen speichern und nur über die vorgesehene Freigabefunktion veröffentlichen.'],{area:'SOP und Academy',flow:['Ergebnis auswählen','Auswertung prüfen','Nachbesprechen','Prüfung verwalten','Veröffentlichen']}),
item('SOP-EH-110','Archiv durchsuchen und Historie eines Datensatzes prüfen',['Bereich Archiv öffnen.','Zeitraum, Typ, Status, Land oder Dokumententyp nach Bedarf filtern.','Suchbegriff eingeben und Suche ausführen.','Treffer anhand von Datum, Nummer, Beschreibung und Status identifizieren.','Datensatz öffnen und Detailinformationen sowie zugehörige Dokumente prüfen.','Historie beziehungsweise Audit-Informationen öffnen und Änderungen, Bearbeiter und Zeitpunkte nachvollziehen.'],{area:'Archiv, Diagnose, Release und App',flow:['Archiv öffnen','Filter setzen','Suchen','Datensatz öffnen','Historie prüfen']}),
item('SOP-EH-111','Protokolle und Audit-Nachweise im ExportHUB prüfen',['Protokoll- beziehungsweise Historienbereich des betroffenen Moduls öffnen.','Zeitraum und Vorgang eingrenzen.','Einträge anhand von Zeitstempel, Benutzer, Aktion und Datensatz prüfen.','Bei einer Untersuchung relevante Einträge vollständig lesen und nicht nur die letzte Meldung betrachten.','Nachweis nur über die vorgesehene Export-/Anzeigeart verwenden und keine Protokolle manuell verändern.'],{area:'Archiv, Diagnose, Release und App',flow:['Protokoll öffnen','Eingrenzen','Einträge prüfen','Nachweis verwenden']}),
item('SOP-EH-112','Fehlerdiagnose öffnen und Systemstörung dokumentieren',['Bei einer ExportHUB-Fehlermeldung den betroffenen Vorgang nicht mehrfach blind wiederholen.','Fehlerdiagnose über die vorgesehene Funktion öffnen.','Fehlertext, Bereich, Firma, Referenz und technischen Diagnosehinweis prüfen.','Diagnoseinformationen speichern beziehungsweise über die vorgesehene Weiterleitung bereitstellen.','Wenn falsche Daten entstehen könnten, die fachliche Bearbeitung bis zur Klärung stoppen.','Nach einer Korrektur denselben Vorgang gezielt einmal erneut prüfen.'],{area:'Archiv, Diagnose, Release und App',flow:['Fehler erkennen','Diagnose öffnen','Informationen prüfen','Dokumentieren','Gezielt erneut testen']}),
item('SOP-EH-113','Fehlerdiagnose über Mobilbenachrichtigung öffnen',['ExportHUB-Fehlerbenachrichtigung auf dem Mobilgerät antippen.','Prüfen, ob die App ohne unnötigen Zwischenschritt zur zugehörigen Diagnose beziehungsweise Meldung navigiert.','Firma, Fehlerzeitpunkt und betroffenen Bereich kontrollieren.','Diagnosedetails öffnen und erforderliche Aktion ableiten.','Bei fehlerhaftem Deep-Link die Meldung über den normalen Diagnosebereich öffnen und den Linkfehler dokumentieren.'],{area:'Archiv, Diagnose, Release und App',flow:['Push öffnen','Diagnose laden','Kontext prüfen','Fehler bearbeiten'],references:['SOP-EH-112']}),
item('SOP-EH-114','Release Center – offene Änderungen prüfen und freigeben',['Release Center mit administrativer Berechtigung öffnen.','Liste und Zähler der offenen nicht veröffentlichten Änderungen prüfen.','Einzelne Änderung öffnen und Beschreibung, betroffene Funktion und Prüfstatus lesen.','Nur vollständig geprüfte Änderung über die vorgesehene Bestätigungs-/Freigabefunktion freigeben.','Nach der Freigabe prüfen, dass Eintrag, Zähler, Scrollposition und verbleibende offene Änderungen konsistent sind.','Eine fehlgeschlagene Freigabe nicht als abgeschlossen behandeln; Fehlerdiagnose verwenden.'],{area:'Archiv, Diagnose, Release und App',flow:['Release Center öffnen','Offene Änderungen prüfen','Änderung öffnen','Freigeben','Status prüfen']}),
item('SOP-EH-115','Gemeinsamen Versionsstand für Produktion, TESTSERVICE und Demo prüfen',['Versions-/Releaseanzeige öffnen beziehungsweise die im System sichtbaren Versionsmarker prüfen.','Produktion, TESTSERVICE und Demo auf dieselbe freigegebene Versionsnummer kontrollieren.','Bei einer geplanten Freigabe sicherstellen, dass der gemeinsame Drei-Umgebungen-Release verwendet wird.','Nach Deployment Live-Prüfung für Produktion, TESTSERVICE und Demo durchführen.','Bei einer abweichenden Version keine einzelne Umgebung stillschweigend weiterführen, sondern den gemeinsamen Versionsstand wiederherstellen.','Ausnahme nur verwenden, wenn ausdrücklich eine abweichende Systemversion angeordnet wurde.'],{area:'Archiv, Diagnose, Release und App',flow:['Versionen prüfen','Gemeinsamen Release starten','Alle Umgebungen testen','Abweichung korrigieren'],references:['SOP-EH-114']}),
item('SOP-EH-116','Demo und Android-App – Umgebung wählen und Update prüfen',['In der Demo prüfen, dass die Umgebung eindeutig als Demo erkennbar ist und ausschließlich Demonstrationsdaten verwendet werden.','In der Android-App die vorgesehene Umgebungswahl öffnen.','Produktion, TESTSERVICE oder Demo entsprechend dem beabsichtigten Zweck auswählen.','Nach dem Wechsel prüfen, dass die sichtbare Umgebung und Version zur Auswahl passen.','Update-Funktion beziehungsweise bereitgestellten Versionshinweis prüfen und nur die freigegebene gemeinsame Version verwenden.','Bei einer Benachrichtigung den direkten Zielaufruf gemäß SOP-EH-007 prüfen.'],{area:'Archiv, Diagnose, Release und App',flow:['Demo prüfen','Umgebung wählen','Version prüfen','Update prüfen','Direktlink testen'],references:['SOP-EH-007','SOP-EH-115']})
];
const AREAS=[...new Set(documents.map(doc=>doc.area))];
const byNumber=Object.freeze(Object.fromEntries(documents.map(doc=>[doc.number,doc])));
root.ExportHubIsoSopCatalog=Object.freeze({version:'RC1008',systemOnly:true,documents:Object.freeze(documents.slice()),areas:Object.freeze(AREAS),byNumber,externalReferences:EXTERNAL_REFERENCES,get(number){return byNumber[String(number||'').trim()]||null;}});
})(typeof globalThis!=='undefined'?globalThis:this);
